//! The brush shape textures (S45, DECISIONS D72), generated by `cargo shape-assets`
//! (`xtask/src/shapes.rs`): per texel of 256 x 256, the signed distance from its centre to the
//! shape's rim in sixteenths of a texel around 128 (positive inside). The evaluator reads the
//! distance where a texel covers at least an output pixel, so the rim stays one output pixel
//! sharp however far a stamp is enlarged, and the coverage (`clamp(0.5 + d, 0, 1)`) from a mip
//! chain of box means where it covers less, so a small stamp neither flickers nor aliases.
//!
//! Uploaded after the paper in the evaluator's textures (`program.rs`): per texture its levels,
//! finest first, each row major; per texel the coverage in the low 16 bits (in 65535ths) and, at
//! the finest level, the distance byte in bits 16 to 23.

use openpaint_core::ShapeTexture;

const CHALK: &[u8] = include_bytes!("../assets/shape-chalk.bin");
const GRAINY: &[u8] = include_bytes!("../assets/shape-grainy.bin");
const SPLATTER: &[u8] = include_bytes!("../assets/shape-splatter.bin");
const ROUGH_SQUARE: &[u8] = include_bytes!("../assets/shape-rough-square.bin");

/// Texels per side of a shape texture.
pub(crate) const SHAPE_SIZE: u32 = 256;
/// Its levels: 256 down to 1 texel per side.
pub(crate) const SHAPE_LEVELS: u32 = 9;
/// The coverage's whole numbers.
const COVERAGE_ONE: f64 = 65_535.0;

/// The bytes of `texture`.
pub(crate) fn shape_bytes(texture: ShapeTexture) -> &'static [u8] {
    match texture {
        ShapeTexture::Chalk => CHALK,
        ShapeTexture::Grainy => GRAINY,
        ShapeTexture::Splatter => SPLATTER,
        ShapeTexture::RoughSquare => ROUGH_SQUARE,
    }
}

/// Where `texture` lies among the shape textures.
pub(crate) fn shape_index(texture: ShapeTexture) -> u32 {
    ShapeTexture::ALL
        .iter()
        .position(|each| *each == texture)
        .map_or(0, |at| at as u32)
}

/// Words one texture takes: every level's texels.
pub(crate) const fn shape_words() -> u32 {
    let (mut words, mut side, mut level) = (0, SHAPE_SIZE, 0);
    while level < SHAPE_LEVELS {
        words += side * side;
        side /= 2;
        level += 1;
    }
    words
}

/// The coverage of a texel whose distance byte is `byte`: the share of it inside the rim, as a
/// box filter over the rim's straight edge.
pub(crate) fn coverage(byte: u8) -> f64 {
    (0.5 + (f64::from(byte) - 128.0) / 16.0).clamp(0.0, 1.0)
}

/// Every texture's words, in `ShapeTexture::ALL` order.
pub(crate) fn shapes() -> Vec<u32> {
    let mut words = Vec::with_capacity((shape_words() * 4) as usize);
    for texture in ShapeTexture::ALL {
        let bytes = shape_bytes(texture);
        let mut level: Vec<f64> = bytes.iter().map(|byte| coverage(*byte)).collect();
        words.extend(
            level
                .iter()
                .zip(bytes)
                .map(|(share, byte)| quantised(*share) | u32::from(*byte) << 16),
        );
        let mut side = SHAPE_SIZE as usize;
        while side > 1 {
            let half = side / 2;
            let at = |x: usize, y: usize| level[y * side + x];
            level = (0..half * half)
                .map(|k| {
                    let (x, y) = (2 * (k % half), 2 * (k / half));
                    (at(x, y) + at(x + 1, y) + at(x, y + 1) + at(x + 1, y + 1)) * 0.25
                })
                .collect();
            words.extend(level.iter().map(|share| quantised(*share)));
            side = half;
        }
    }
    words
}

fn quantised(share: f64) -> u32 {
    (share * COVERAGE_ONE).round() as u32
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_texture_is_a_full_chain_with_its_mean_at_the_top() {
        let words = shapes();
        assert_eq!(shape_words(), 87_381);
        assert_eq!(words.len(), 4 * 87_381);
        for (k, texture) in ShapeTexture::ALL.into_iter().enumerate() {
            let bytes = shape_bytes(texture);
            assert_eq!(bytes.len(), (SHAPE_SIZE * SHAPE_SIZE) as usize);
            let mean = bytes.iter().map(|byte| coverage(*byte)).sum::<f64>() / bytes.len() as f64;
            let top = words[(k as u32 * shape_words() + shape_words() - 1) as usize];
            let top = f64::from(top & 0xffff) / COVERAGE_ONE;
            assert!((top - mean).abs() < 1e-4, "{texture:?}: {top} for {mean}");
            assert!(mean > 0.1 && mean < 0.9, "{texture:?}: {mean}");
            assert_eq!(shape_index(texture), k as u32);
        }
    }
}
